using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
sealed partial class Companion {
 Size roundedSize;bool roundedState;internal NoteBackground noteBackground;
 internal void ApplyFloating(){foreach(var strip in new[]{top,memoTools})if(strip!=null)foreach(ToolStripItem item in strip.Items)if(item.Text=="Minimise"||item.Text=="Maximise")item.Enabled=!IsTabbed;ApplyMemoView();if(captureButton!=null&&!captureButton.IsDisposed)captureButton.Opacity=Math.Max(.3,store.Pref.WidgetOpacity/100.0);if(IsTabbed){if(noteBackground!=null)noteBackground.Set(100,CompanionPalette.For(store.Pref.Theme)[1],false);Opacity=1;return;}TopMost=store.Pref.Top;FormBorderStyle=store.Pref.Borderless?FormBorderStyle.None:FormBorderStyle.Sizable;RoundWindow();if(noteBackground==null)noteBackground=new NoteBackground(this);noteBackground.Set(store.Pref.Opacity,CompanionPalette.For(store.Pref.Theme)[1],store.Pref.Borderless);}
 internal void SetMemo(bool enabled){store.Pref.Memo=enabled;if(enabled){store.Pref.Borderless=true;Compact(true);if(tasks.Items.Count>0)SetView("Tasks");}else Compact(false);ApplyMemoView();store.SavePrefs();}
 internal void ApplyMemoView(){bool minimal=store.Pref.Memo&&!IsTabbed;top.Visible=quick.Visible=status.Visible=!minimal;if(memoTools!=null)memoTools.Visible=minimal;if(viewTools!=null)viewTools.Visible=!minimal;heading.TextAlign=minimal?ContentAlignment.MiddleCenter:ContentAlignment.MiddleLeft;heading.Height=minimal?42:46;heading.Padding=minimal?new Padding(4):new Padding(12,8,0,0);taskTools.Visible=view=="Tasks"&&!minimal;UpdateWritingHeader();}
 internal void SetupMemoHeader(){heading.MouseDown+=(s,e)=>{if(e.Button==MouseButtons.Left&&store.Pref.Memo&&!IsTabbed&&!store.Pref.Locked){Native.ReleaseCapture();Native.DragWindow(Handle);}};heading.DoubleClick+=(s,e)=>{if(store.Pref.Memo)SetMemo(false);else RenamePage(current);};var menu=new ContextMenuStrip();menu.Items.Add("Full notebook window",null,(s,e)=>SetMemo(false));menu.Items.Add("Show note text",null,(s,e)=>SetView("Notes"));menu.Items.Add("Task view",null,(s,e)=>SetView("Tasks"));menu.Items.Add("New note",null,(s,e)=>NewNote("Quick note",""));menu.Items.Add("Opacity & window appearance…",null,(s,e)=>FloatingAppearance());menu.Items.Add("Lock / unlock position",null,(s,e)=>{store.Pref.Locked=!store.Pref.Locked;store.SavePrefs();});menu.Items.Add("Settings…",null,(s,e)=>Settings());menu.Items.Add("Hide to tray",null,(s,e)=>Hide());heading.ContextMenuStrip=menu;}
 internal void RoundWindow(){if(!IsHandleCreated||IsTabbed)return;bool rounded=store.Pref.Borderless&&WindowState!=FormWindowState.Maximized;if(roundedSize==Size&&roundedState==rounded)return;roundedSize=Size;roundedState=rounded;if(!store.Pref.Borderless||WindowState==FormWindowState.Maximized){if(Region!=null){Region.Dispose();Region=null;}return;}int radius=14,w=Width,h=Height;using(var path=new GraphicsPath()){path.AddArc(0,0,radius*2,radius*2,180,90);path.AddArc(w-radius*2,0,radius*2,radius*2,270,90);path.AddArc(w-radius*2,h-radius*2,radius*2,radius*2,0,90);path.AddArc(0,h-radius*2,radius*2,radius*2,90,90);path.CloseFigure();var old=Region;Region=new Region(path);if(old!=null)old.Dispose();}}
 internal void FloatingAppearance(){using(var f=Dialog("Floating memo appearance",520,350)){var opacity=new ThemeSlider{Minimum=30,Maximum=100,Value=Math.Max(30,Math.Min(100,store.Pref.Opacity)),Dock=DockStyle.Top,TickFrequency=10};var value=new Label{Text="Opacity · "+opacity.Value+"%",Dock=DockStyle.Top,Height=36};var borderless=new CheckBox{Text="Hide traditional window borders",Checked=store.Pref.Borderless,Dock=DockStyle.Top,Height=40};var pin=new CheckBox{Text="Always on top",Checked=store.Pref.Top,Dock=DockStyle.Top,Height=40};var close=new Button{Text="Done",Dock=DockStyle.Bottom,Height=40};close.Click+=(s,e)=>f.Close();opacity.ValueChanged+=(s,e)=>{store.Pref.Opacity=opacity.Value;value.Text="Opacity · "+opacity.Value+"%";ApplyFloating();};borderless.CheckedChanged+=(s,e)=>{store.Pref.Borderless=borderless.Checked;ApplyFloating();};pin.CheckedChanged+=(s,e)=>{store.Pref.Top=pin.Checked;if(!IsTabbed)TopMost=pin.Checked;};f.Controls.Add(new Label{Text="Drag the empty header to move. Resize from the sides or bottom corners. Window > Lock position prevents accidental changes. Tray > Restore full window resets transparency and borders.",Dock=DockStyle.Fill});f.Controls.Add(opacity);f.Controls.Add(value);f.Controls.Add(pin);f.Controls.Add(borderless);f.Controls.Add(close);ThemeControls(f);f.ShowDialog(this);store.SavePrefs();}}
}
